/// <summary>
/// assiging return order components
/// </summary>
public class METSalesPriceComponents_Sales extends METSalesPriceComponents
{   
}

Method.Source:
/// <summary>
/// Query ranges
/// </summary>
/// <param name = "qbdsSalesLine">QueryBuildDataSource</param>
/// <param name = "_salesLine">SalesLine</param>
/// <param name = "_metSalesTabel">METSalesTable</param>
public void queryRange(QueryBuildDataSource qbdsSalesLine, SalesLine _salesLine, METSalesTable _metSalesTabel)
{
    qbdsSalesLine.addRange(fieldNum(SalesLine, RecId)).value(any2Str(_salesLine.RecId));
}

/// <summary>
/// assig return values
/// </summary>
/// <param name = "_priceComponent">METSalesLinePriceComponent</param>
/// <param name = "_salesLine">SalesLine</param>
/// <param name = "_tmpTable">METSalesLinePriceComponentTmp</param>
public void setValues(METSalesLinePriceComponent _priceComponent,
                       SalesLine _salesLine,
                       METSalesLinePriceComponentTmp _tmpTable,
                       SalesLine _orgSalesLine)
{
    METGrossWeight actualWeight;

    tmpTable.Value    = _priceComponent.Value;

    if (pdsGlobal::pdsIsCWItem(_salesLine.ItemId))
    {
        actualWeight = _salesLine.displayMETActualWeight();
    }

    if (actualWeight)
    {
        tmpTable.ExtValue = tmpTable.Value * actualWeight;
    }
    else
    {
        tmpTable.ExtValue = tmpTable.Value * _orgSalesLine.SalesQty;
    }

}
